const panel = document.getElementById('ai4a11y-describe-panel');
if (!panel) return false;

// Role dialog with accessible name
if (panel.getAttribute('role') !== 'dialog') return false;
const panelName = panel.getAttribute('aria-label') || panel.getAttribute('aria-labelledby');
if (!panelName) return false;

const closeBtn = panel.querySelector('.ai4a11y-describe-close');
if (!closeBtn) return false;
if (closeBtn.tagName !== 'BUTTON' || closeBtn.type !== 'button') return false;
if (!closeBtn.getAttribute('aria-label')) return false;

// Target size check (WCAG 2.5.8: at least 24x24)
const btnRect = closeBtn.getBoundingClientRect();
if (btnRect.width < 24 || btnRect.height < 24) return false;

// Visible focus check (WCAG 2.4.7, 1.4.11)
closeBtn.focus();
const computed = window.getComputedStyle(closeBtn);
const outlineWidth = parseFloat(computed.outlineWidth) || 0;
if (outlineWidth < 2) return false;
closeBtn.blur();

// Focus not obscured check (WCAG 2.4.11)
const pRect = panel.getBoundingClientRect();
const hit = document.elementFromPoint(pRect.right - 14, pRect.top + 14);
if (hit !== closeBtn && !closeBtn.contains(hit)) return false;

// Dismiss
closeBtn.click();
return true;

